choose.when:
select product_id from product.product_sku where product_status = 1 and status = 1
and product_id in ( select id from product.product where product.status = 1 and category_id = #{categoryId} )
group by product_id order by min(price) desc limit #{offset}, #{size}

select product_id from product.product_sku where product_status = 1 and status = 1
and product_id in ( select id from product.product where product.status = 1 and category_id = #{categoryId} )
group by product_id order by min(price) limit #{offset}, #{size}

choose.otherwise:
select id
from product.product
where status = 1

    and category_id = #{categoryId}

order by created_time desc
limit #{offset}, #{size}
